const key="naturia:v2:itinerary";let saved=[];try{saved=JSON.parse(localStorage.getItem(key)||"[]")}catch(e){saved=[]}if(!Array.isArray(saved))saved=[];saved=saved.filter(id=>D.places.some(p=>p.id===id));
