(function naturiaJournal(){
"use strict";
const D=window.NATURIA_DATA,root=document.getElementById("content"),key="naturia:v2:journal";
const esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
let entries=[];try{entries=JSON.parse(localStorage.getItem(key)||"[]")}catch(e){entries=[]}if(!Array.isArray(entries))entries=[];
const special=["🌸","🌊","🌿","☀️","🪸","🍃","🌼","⭐"];
function save(){try{localStorage.setItem(key,JSON.stringify(entries))}catch(e){document.getElementById("nj-message").textContent="Storage unavailable. Export a copy instead."}}
function display(){
 const cards=document.getElementById("nj-entries");if(!cards)return;
 cards.innerHTML=entries.length?entries.slice().reverse().map((n,i)=>{const p=D.places.find(x=>x.id===n.place);
 return `<article class="nj-entry"><div class="nj-stamp" aria-label="Travel stamp">${special[Math.abs(n.seed)%special.length]}</div><div class="nj-note"><span class="nj-date">${esc(n.date)} · ${esc(n.mood)}</span><h3>${esc(p?p.name:n.title||"My naturist journey")}</h3><p>${esc(n.note)}</p>${p?`<a href="#/place/${encodeURIComponent(p.id)}">Read destination notes ↗</a>`:""}</div><button type="button" data-jremove="${esc(n.id)}" aria-label="Remove journal entry">×</button></article>`}).join(""):'<div class="v2-feature-note">Your journal is empty. Add a little postcard or a note about a destination you hope to explore.</div>';
 document.querySelectorAll("[data-jremove]").forEach(b=>b.onclick=()=>{entries=entries.filter(x=>x.id!==b.dataset.jremove);save();display()});
 document.getElementById("nj-count").textContent=entries.length+" saved "+(entries.length===1?"postcard":"postcards");
}
function render(){
const route=(location.hash||"#/home").replace(/^#\/?/,"").split("/")[0];if(route!=="journal")return;
const destinations=D.places.filter(p=>p.type!=="alert").sort((a,b)=>a.country.localeCompare(b.country)||a.name.localeCompare(b.name));
root.innerHTML=`<section class="v2-cover"><div class="page-width"><div class="v2-overline">✿ NATURIA • PRIVATE TRAVEL JOURNAL</div><h1>Your little <em>world diary.</em></h1><p>A postcard diary with original illustrated stamps and personal notes. No photographs, no account, no cloud sync — all entries stay on this device.</p><div class="v2-breadcrumb"><a href="#/home">Home</a> › Journal</div></div></section><div class="page-width v2-main"><div class="v2-feature-note">🔐 Your notes are saved in this browser's local storage, which can be cleared by your browser. Export a backup if they matter to you. Entries are not published or uploaded.</div><div class="v2-planner"><section class="v2-panel"><h2>💌 Write a postcard</h2><div class="nj-form"><label>Date<input id="nj-date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label>Destination<select id="nj-place"><option value="">A place in my imagination</option>${destinations.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} — ${esc(p.area)}</option>`).join("")}</select></label><label>Feeling<select id="nj-mood"><option>Dreaming</option><option>Planning</option><option>Visited</option><option>Learning</option></select></label><label>My note<textarea id="nj-text" rows="7" maxlength="3000" placeholder="The air, the sea, the questions I want to ask, and what I hope to remember…"></textarea></label><button class="v2-button" id="nj-save">Save postcard</button><p role="status" id="nj-message" class="v2-small"></p></div></section><aside class="v2-panel"><h2>🌸 My travel stamps</h2><p id="nj-count"></p><div class="nj-stamp-gallery">${special.map(s=>`<span>${s}</span>`).join("")}</div><p>Each postcard receives a small illustrated stamp. It is a personal journal, not a certificate of having visited or of local legal permission.</p><div class="v2-button-row"><button class="v2-button" id="nj-export">Export JSON</button><button class="v2-button alt" id="nj-clear">Clear journal</button></div><p class="v2-small">The exported file may contain personal notes. Store it privately.</p></aside></div><section class="v2-panel"><h2>Saved postcards</h2><div id="nj-entries"></div></section></div>`;
document.getElementById("nj-save").onclick=()=>{const note=document.getElementById("nj-text").value.trim();if(!note){document.getElementById("nj-message").textContent="Write a note before saving.";return;}const date=document.getElementById("nj-date").value,mood=document.getElementById("nj-mood").value,place=document.getElementById("nj-place").value;entries.push({id:"j"+Date.now()+"-"+Math.floor(Math.random()*100000),date,mood,place,note,seed:entries.length%8});save();document.getElementById("nj-text").value="";document.getElementById("nj-message").textContent="Postcard saved on this device.";display()};
document.getElementById("nj-export").onclick=()=>{const data=JSON.stringify({app:"Naturia Journal",exported:new Date().toISOString().slice(0,10),entries},null,2);const url=URL.createObjectURL(new Blob([data],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download="naturia-private-journal.json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
document.getElementById("nj-clear").onclick=()=>{if(confirm("Permanently clear the journal saved in this browser?")){entries=[];save();display()}};
display();
document.title="Private Travel Journal · Naturia";
}
window.NATURIA_JOURNAL_RENDER = render;
})();

