 let n=spots.filter(p=>p.country===c.code&&p.type!=='alert').length;
 return `<article class="panel soft country-card"><div class="country-top"><span class="flag" aria-hidden="true">${c.flag}</span><span class="pill ${c.depth==='detailed'?'':'slate'}">${c.depth==='detailed'?'Researched guide':'Starter guide'}</span></div><h3>${esc(c.name)}</h3><div class="label">${esc(c.region)}</div><p>${esc(c.label)}. ${esc(c.culture.slice(0,110))}${c.culture.length>110?'…':''}</p><div class="mini-meta"><small>${n?`${n} mapped ${n===1?'place':'places'}`:'No verified place yet'}</small><a class="link-more" href="${countryUrl(c.code)}">View guide</a></div></article>`
