function header({kicker,title,desc,crumb=[]}){return `<section class="page-hero"><div class="page-width">${crumb.length?bread(crumb):''}<span class="eyebrow">${esc(kicker)}</span><h1>${title}</h1><p>${desc}</p></div></section>`}
function section({title,desc,button='',content,cls=''}){return `<section class="section ${cls}"><div class="page-width"><div class="section-heading"><div><h2>${title}</h2>${desc?`<p class="muted">${desc}</p>`:''}</div>${button}</div>${content}</div></section>`}
